// WARNING: the sheet stack below is for OPEN EXTERIORS only. With props standing in the band (crates, walls, characters)
// the sheets cut through them — use a height-falloff fog term or a floor-hugging texture instead (see intent).
import * as THREE from 'three';
export function setupFog(scene, horizon = 0x2f5d8c) { scene.fog = new THREE.FogExp2(horizon, 0.006); } // <= 0.008 for winter exteriors
function noiseAlpha(n = 64, rng = Math.random) {                  // alphaMap reads the green channel, so fill RGBA
  const data = new Uint8Array(n * n * 4);
  for (let i = 0; i < n * n; i++) { const v = 140 + Math.floor(rng() * 115); data.set([v, v, v, 255], i * 4); }
  const tex = new THREE.DataTexture(data, n, n, THREE.RGBAFormat);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping; tex.repeat.set(6, 6); tex.needsUpdate = true; return tex;
}
export function makeMistBand(size = 120, top = 1.2, rng = Math.random) {
  const group = new THREE.Group(); group.userData.tag = 'mist';
  const alpha = noiseAlpha(64, rng);
  [0.25, 0.6, 1.0].forEach((y, i) => {                             // three thin sheets inside 0-1.2 m, densest at the ground
    const mat = new THREE.MeshBasicMaterial({ color: 0x8fa3b8, transparent: true, depthWrite: false, alphaMap: alpha,
      opacity: 0.28 * (1 - y / top), fog: true });                  // scalar opacity <= 0.3
    const m = new THREE.Mesh(new THREE.PlaneGeometry(size, size), mat);
    m.rotation.x = -Math.PI / 2; m.position.y = y; m.renderOrder = 10 + i; m.userData.tag = 'mist';
    group.add(m);
  });
  return group;
}
export function tickMist(group, t) {
  group.children.forEach((m, i) => m.material.alphaMap.offset.set(t * 0.004 * (i + 1), t * 0.002));
}
